using System;
using System.Collections.Generic;
using UnityEngine;
namespace SpeedStars.Themes {
 public sealed partial class ThemedLoopWay {
  readonly List<int[]> skyDecks=new List<int[]>();
  void ResetSkyLayout(){skyDecks.Clear();}
  int SkyChoice(int number){int count=theme.landmarks.Length;int cycle=number/count;while(skyDecks.Count<=cycle){int c=skyDecks.Count;var order=new List<int>();for(int i=0;i<count;i++)order.Add(i);var r=new System.Random(Hash(seed,c+9821));for(int i=count-1;i>0;i--){int j=r.Next(i+1),t=order[i];order[i]=order[j];order[j]=t;}if(c>0&&order[0]==skyDecks[c-1][count-1]){int t=order[0];order[0]=order[1];order[1]=t;}skyDecks.Add(order.ToArray());}return skyDecks[cycle][number%count];}  void BuildSkyLayout(Transform root,ThemeChunk chunk,float a,float b,int index,int sectionSeed){var r=new System.Random(Hash(sectionSeed,781));var islands=Group("Individually Composed Sky Islands",root);var clouds=Group("Volume Clouds Concealing Island Roots",root);const float step=23;var names=new List<string>();for(int n=Mathf.Max(0,Mathf.FloorToInt((a-StartZ)/step)-1);n<=Mathf.CeilToInt((b-StartZ)/step)+1;n++){var random=new System.Random(Hash(seed,n+7171));float z=StartZ+n*step+R(random,5,12);if(z<a||z>=b)continue;var asset=theme.landmarks[SkyChoice(n)];float yaw=270+R(random,-9,9),scale=R(random,.48f,.62f);var bounds=MeasuredRomanBounds(asset,Vector3.one*scale,yaw);float front=R(random,-35,-30),height=R(random,.65f,1.25f);float roof=height+bounds.max.y;float limit=1.65f+(1.37f-front)*.125f;if(roof>limit)scale*=Mathf.Max(.2f,(limit-height)/Mathf.Max(.1f,bounds.max.y));bounds=MeasuredRomanBounds(asset,Vector3.one*scale,yaw);var p=new Vector3(front-bounds.max.x,height,z-bounds.center.z);Item(asset,islands,p,yaw,scale);names.Add(asset.name);for(int i=0;i<3;i++)SkyVolume(clouds,"Independent Island Volume Root Cover",new Vector3(front+.8f+i*.15f,height-.9f,z+(i-1)*bounds.size.z*.2f),new Vector3(bounds.size.z*1.65f,4.5f,1),random);}
   var far=Group("Quiet Distant Sky Territories",root);const float farStep=83;for(int n=Mathf.Max(0,Mathf.FloorToInt((a-StartZ)/farStep));n<=Mathf.CeilToInt((b-StartZ)/farStep);n++){var random=new System.Random(Hash(seed,n+9151));float z=StartZ+n*farStep+35;if(z<a||z>=b||theme.background.Length==0)continue;var asset=theme.background[(n+Mathf.Abs(seed%theme.background.Length))%theme.background.Length];var obj=Item(asset,far,new Vector3(R(random,-81,-68),R(random,1,2),z),270+R(random,-12,12),R(random,.5f,.7f));var bounds=BoundsIn(obj,transform);SkyVolume(clouds,"Distant Island Root Cloud",new Vector3(bounds.max.x+1,obj.transform.localPosition.y-.9f,z),new Vector3(bounds.size.z*1.5f,5,1),random);}
   if(index%3==1&&theme.accent.Length>0){var rainbows=Group("Rare Rainbow Above Cloud Sea",root);var rainbow=Item(theme.accent[0],rainbows,new Vector3(-115,-20,a+43),270,4.5f);foreach(float side in new[]{-1f,1f}){var world=rainbow.transform.TransformPoint(new Vector3(side*8.8f,3,0));var p=transform.InverseTransformPoint(world);SkyVolume(clouds,"Rainbow Volume Cloud Foot",p,new Vector3(24,9,1),r);}}
   BuildSkyCloudDeck(root,a,b,sectionSeed);chunk.landmarkSummary=string.Join(", ",names.ToArray());
  }
 }
}
